/* =========================================================================
   SPEED RAYS - GPU HARDWARE ACCELERATED RELATIVISTIC VELOCITY SHOWCASE
   ========================================================================= */

.speed-rays-container {
  position: relative;
  width: 100%;
  min-height: 480px;
  background: #000000;
  border-radius: 14px;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 100px 32px 90px 32px;
  box-sizing: border-box;
  container-type: inline-size;
}

/* Size Variants */
.speed-rays-container.size-sm {
  min-height: 340px;
  padding: 50px 20px 45px 20px;
}

.speed-rays-container.size-sm .speed-rays-title {
  font-size: clamp(1.35rem, 2vw, 1.85rem);
  white-space: nowrap;
}

.speed-rays-container.size-sm .speed-rays-description {
  font-size: 13px;
  max-width: 520px;
  margin-top: 12px;
}

.speed-rays-container.size-lg {
  min-height: 520px;
  padding: 110px 40px 100px 40px;
}

.speed-rays-container.size-lg .speed-rays-title {
  font-size: clamp(1.85rem, 3vw, 2.65rem);
  white-space: nowrap;
}

.speed-rays-container.size-lg .speed-rays-description {
  font-size: 15.5px;
  max-width: 680px;
  margin-top: 16px;
}

/* Background Field */
.speed-rays-field {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  pointer-events: none;
  z-index: 1;
  transform: translateZ(0);
  container-type: inline-size;
}

/* Atmospheric Vignette Overlay */
.speed-rays-vignette {
  position: absolute;
  inset: 0;
  background: radial-gradient(
    circle at center,
    rgba(0, 0, 0, 0.05) 0%,
    rgba(0, 0, 0, 0.72) 80%,
    #000000 100%
  );
  pointer-events: none;
  z-index: 2;
}

/* Foreground Content */
.speed-rays-content {
  position: relative;
  z-index: 3;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  max-width: 920px;
  width: 100%;
  margin: 0 auto;
  pointer-events: auto;
}

/* Headline - Refined, elegant single-row title */
.speed-rays-title {
  font-size: clamp(1.6rem, 2.6vw, 2.35rem);
  font-weight: 400;
  line-height: 1.2;
  letter-spacing: -0.025em;
  color: #ffffff;
  margin: 0;
  padding: 0;
  white-space: nowrap;
  text-shadow: 0 0 30px rgba(255, 255, 255, 0.12);
}

/* Description */
.speed-rays-description {
  margin-top: 14px;
  max-width: 620px;
  font-size: 14px;
  line-height: 1.62;
  color: rgba(255, 255, 255, 0.6);
  font-weight: 400;
  letter-spacing: 0.005em;
}

/* High-Tech Metrics Bar */
.speed-rays-stats-row {
  margin-top: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  flex-wrap: wrap;
}

.speed-rays-stat-item {
  display: flex;
  align-items: baseline;
  gap: 7px;
}

.speed-rays-stat-val {
  font-family: 'JetBrains Mono', 'SF Mono', 'Fira Code', Menlo, monospace;
  font-size: 13.5px;
  font-weight: 600;
  color: #ffffff;
  letter-spacing: -0.01em;
}

.speed-rays-stat-lbl {
  font-size: 9.5px;
  font-weight: 500;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.44);
}

/* Vertical Hairline Divider */
.speed-rays-stat-divider {
  width: 1px;
  height: 14px;
  background: rgba(255, 255, 255, 0.18);
}

/* Base Velocity Dash */
.speed-ray-dash {
  position: absolute;
  left: 0;
  border-radius: 9999px;
  will-change: transform, opacity;
  transform: translate3d(-160px, 0, 0);
  animation-name: streamDash;
  animation-timing-function: linear;
  animation-iteration-count: infinite;
}

/* =========================================================================
   THEME COLORWAYS: Primary, Secondary, Tertiary Lasers
   ========================================================================= */

/* 1. BLACK / COSMIC CHROME THEME (Default) */
.theme-black .ray-white {
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(255, 255, 255, 0.15) 20%,
    rgba(255, 255, 255, 0.95) 90%,
    #ffffff 100%
  );
  box-shadow: 0 0 10px 1px rgba(255, 255, 255, 0.45);
}

.theme-black .ray-red {
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(185, 28, 28, 0.15) 20%,
    rgba(239, 68, 68, 0.8) 80%,
    rgba(254, 202, 202, 0.95) 100%
  );
  box-shadow: 0 0 10px 1px rgba(220, 38, 38, 0.4);
}

.theme-black .ray-purple {
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(126, 34, 206, 0.15) 20%,
    rgba(168, 85, 247, 0.8) 80%,
    rgba(233, 213, 255, 0.95) 100%
  );
  box-shadow: 0 0 10px 1px rgba(168, 85, 247, 0.4);
}

/* 2. AMBER / CHAMPAGNE GOLD THEME */
.theme-amber .ray-white {
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(254, 243, 199, 0.15) 20%,
    rgba(251, 191, 36, 0.95) 90%,
    #ffffff 100%
  );
  box-shadow: 0 0 10px 1px rgba(245, 158, 11, 0.5);
}

.theme-amber .ray-red {
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(217, 119, 6, 0.15) 20%,
    rgba(245, 158, 11, 0.85) 80%,
    rgba(254, 240, 138, 0.95) 100%
  );
  box-shadow: 0 0 10px 1px rgba(217, 119, 6, 0.45);
}

.theme-amber .ray-purple {
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(180, 83, 9, 0.15) 20%,
    rgba(217, 119, 6, 0.8) 80%,
    rgba(253, 224, 71, 0.95) 100%
  );
  box-shadow: 0 0 10px 1px rgba(180, 83, 9, 0.45);
}

/* 3. BLUE / CRYO SAPPHIRE THEME */
.theme-blue .ray-white {
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(224, 242, 254, 0.15) 20%,
    rgba(56, 189, 248, 0.95) 90%,
    #ffffff 100%
  );
  box-shadow: 0 0 10px 1px rgba(56, 189, 248, 0.5);
}

.theme-blue .ray-red {
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(2, 132, 199, 0.15) 20%,
    rgba(14, 165, 233, 0.85) 80%,
    rgba(186, 230, 253, 0.95) 100%
  );
  box-shadow: 0 0 10px 1px rgba(2, 132, 199, 0.45);
}

.theme-blue .ray-purple {
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(79, 70, 229, 0.15) 20%,
    rgba(99, 102, 241, 0.8) 80%,
    rgba(199, 210, 254, 0.95) 100%
  );
  box-shadow: 0 0 10px 1px rgba(99, 102, 241, 0.45);
}

/* 4. PURPLE / COSMIC AMETHYST THEME */
.theme-purple .ray-white {
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(243, 232, 255, 0.15) 20%,
    rgba(216, 180, 254, 0.95) 90%,
    #ffffff 100%
  );
  box-shadow: 0 0 10px 1px rgba(192, 132, 252, 0.5);
}

.theme-purple .ray-red {
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(147, 51, 234, 0.15) 20%,
    rgba(192, 132, 252, 0.85) 80%,
    rgba(245, 208, 254, 0.95) 100%
  );
  box-shadow: 0 0 10px 1px rgba(147, 51, 234, 0.45);
}

.theme-purple .ray-purple {
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(126, 34, 206, 0.15) 20%,
    rgba(168, 85, 247, 0.8) 80%,
    rgba(233, 213, 255, 0.95) 100%
  );
  box-shadow: 0 0 10px 1px rgba(168, 85, 247, 0.4);
}

/* 5. EMERALD / OCEANIC JADE THEME */
.theme-emerald .ray-white {
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(209, 250, 229, 0.15) 20%,
    rgba(52, 211, 153, 0.95) 90%,
    #ffffff 100%
  );
  box-shadow: 0 0 10px 1px rgba(52, 211, 153, 0.5);
}

.theme-emerald .ray-red {
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(5, 150, 105, 0.15) 20%,
    rgba(16, 185, 129, 0.85) 80%,
    rgba(167, 243, 208, 0.95) 100%
  );
  box-shadow: 0 0 10px 1px rgba(5, 150, 105, 0.45);
}

.theme-emerald .ray-purple {
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(13, 148, 136, 0.15) 20%,
    rgba(20, 184, 166, 0.8) 80%,
    rgba(153, 246, 228, 0.95) 100%
  );
  box-shadow: 0 0 10px 1px rgba(20, 184, 166, 0.45);
}

/* GPU Hardware-Accelerated Flow Keyframe */
@keyframes streamDash {
  0% {
    transform: translate3d(-200px, 0, 0);
    opacity: 0;
  }
  3% {
    opacity: var(--ray-op, 0.85);
  }
  97% {
    opacity: var(--ray-op, 0.85);
  }
  100% {
    transform: translate3d(calc(100cqw + 200px), 0, 0);
    opacity: 0;
  }
}

/* Fallback for browsers or nested viewports without container queries */
@supports not (container-type: inline-size) {
  @keyframes streamDash {
    0% {
      transform: translate3d(-200px, 0, 0);
      opacity: 0;
    }
    3% {
      opacity: var(--ray-op, 0.85);
    }
    97% {
      opacity: var(--ray-op, 0.85);
    }
    100% {
      transform: translate3d(calc(100vw + 200px), 0, 0);
      opacity: 0;
    }
  }
}

/* Mobile Responsiveness */
@media (max-width: 768px) {
  .speed-rays-container {
    padding: 70px 16px 65px 16px;
    min-height: 400px;
  }

  .speed-rays-stats-row {
    gap: 16px;
  }

  .speed-rays-stat-divider {
    display: none;
  }

  .speed-rays-description {
    font-size: 14px;
  }
}

import React, { useMemo } from 'react';
import './SpeedRays.css';

export interface SpeedRayStat {
  value: string;
  label: string;
}

export interface SpeedRaysProps {
  title?: string;
  description?: string;
  stats?: SpeedRayStat[];
  color?: 'black' | 'amber' | 'blue' | 'purple' | 'emerald';
  size?: 'sm' | 'md' | 'lg';
  speed?: number;
  rayCount?: number;
  className?: string;
}

interface RayItem {
  id: number;
  top: number; // vertical % offset
  width: number; // dash length in px
  height: number; // thickness in px
  duration: number; // stream duration in seconds
  delay: number; // pre-warmed negative delay in seconds
  type: 'white' | 'red' | 'purple';
  opacity: number;
}

const DEFAULT_STATS: SpeedRayStat[] = [
  { value: '120 FPS', label: 'GPU PIPELINE' },
  { value: '< 0.4ms', label: 'FRAME DISPATCH' },
  { value: '0 kB', label: 'RUNTIME BLOAT' },
];

export const SpeedRays: React.FC<SpeedRaysProps> = ({
  title = 'Crafted for 120 FPS physical reality.',
  description = 'GPU-accelerated signed distance fields, real-world optical refraction, and incompressible fluid kinematics. Every component renders with pure mathematical precision and zero runtime friction.',
  stats = DEFAULT_STATS,
  color = 'black',
  size = 'md',
  speed = 1,
  rayCount = 54,
  className = '',
}) => {
  // Generate deterministic pre-distributed velocity laser rays
  const rays: RayItem[] = useMemo(() => {
    const items: RayItem[] = [];
    const types: ('white' | 'red' | 'purple')[] = [
      'white',
      'red',
      'white',
      'purple',
      'white',
      'white',
      'red',
      'purple',
      'white',
      'red',
      'white',
      'purple',
    ];

    const count = Math.max(24, rayCount);

    for (let i = 0; i < count; i++) {
      const type = types[i % types.length];
      // Varied lengths: short laser pulses (35px) to long relativistic comet tails (160px)
      const lengthCategory = i % 3;
      let width: number;
      if (lengthCategory === 0) {
        width = 35 + ((i * 13) % 40); // 35px - 75px
      } else if (lengthCategory === 1) {
        width = 75 + ((i * 17) % 50); // 75px - 125px
      } else {
        width = 110 + ((i * 23) % 55); // 110px - 165px
      }

      // Dash thickness: 1px to 1.5px
      const height = i % 4 === 0 ? 1.5 : 1;
      // Distributed vertically across full height (3% to 97%)
      const top = 3 + ((i * 19) % 94);
      // High-velocity stream duration: 1.6s to 4.2s scaled by speed prop
      const baseDuration = (1.6 + ((i * 17) % 26) / 10) / Math.max(0.2, speed);
      // Staggered negative delays so streaks are dynamically distributed across the entire section on load
      const delay = -(((i * 67) % 100) / 100) * baseDuration;
      // Opacity
      const opacity = type === 'white' ? 0.9 : 0.78;

      items.push({
        id: i,
        top,
        width,
        height,
        duration: baseDuration,
        delay,
        type,
        opacity,
      });
    }

    return items;
  }, [rayCount, speed]);

  return (
    <div
      className={`speed-rays-container theme-${color} size-${size} ${className}`.trim()}
      role="region"
      aria-label="High-Velocity Edge Performance"
    >
      {/* Dynamic Animated Comet Streaks */}
      <div className="speed-rays-field" aria-hidden="true">
        {rays.map((ray) => (
          <div
            key={ray.id}
            className={`speed-ray-dash ray-${ray.type}`}
            style={
              {
                top: `${ray.top}%`,
                width: `${ray.width}px`,
                height: `${ray.height}px`,
                animationDuration: `${ray.duration.toFixed(2)}s`,
                animationDelay: `${ray.delay.toFixed(2)}s`,
                '--ray-op': ray.opacity,
              } as React.CSSProperties
            }
          />
        ))}
      </div>

      {/* Atmospheric Vignette Overlay */}
      <div className="speed-rays-vignette" aria-hidden="true" />

      {/* Foreground Content */}
      <div className="speed-rays-content">
        {title && <h2 className="speed-rays-title">{title}</h2>}

        {description && <p className="speed-rays-description">{description}</p>}

        {stats && stats.length > 0 && (
          <div className="speed-rays-stats-row">
            {stats.map((stat, index) => (
              <React.Fragment key={stat.label}>
                <div className="speed-rays-stat-item">
                  <span className="speed-rays-stat-val">{stat.value}</span>
                  <span className="speed-rays-stat-lbl">{stat.label}</span>
                </div>
                {index < stats.length - 1 && (
                  <div className="speed-rays-stat-divider" aria-hidden="true" />
                )}
              </React.Fragment>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default SpeedRays;
